box(ctx,900,324,240,170,'#214b3c');svg(ctx,'mark.svg',980,355,64,'#f2ecdc')
box(ctx,24,538,1152,198,'#ffffff');svg(ctx,'logo.svg',300,551,600,'#000000');label(ctx,50,705,'ONE COLOR')
